import json
import sys
from pathlib import Path


def search_key(title):
    return title.casefold()


def load(path="data/books.json"):
    return json.loads(Path(path).read_text())


def build_export(rows):
    """Search export: every row, original title kept, key = casefolded title.

    Identity is (isbn, edition). Order is (title, isbn, edition) in Python string order.
    """
    books = [
        {"isbn": r["isbn"], "edition": r["edition"], "title": r["title"],
         "active": r["active"], "key": search_key(r["title"])}
        for r in sorted(rows, key=lambda r: (r["title"], r["isbn"], r["edition"]))
    ]
    return {"books": books}


def write_export(path="build/search.json", source="data/books.json"):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(build_export(load(source)), ensure_ascii=False, indent=2) + "\n",
                    encoding="utf-8")
    return path


def search(prefix, books):
    """Rows whose key starts with the casefolded prefix, in the given order."""
    folded = search_key(prefix)
    return [b for b in books if b["key"].startswith(folded)]


if __name__ == "__main__":
    if len(sys.argv) >= 2 and sys.argv[1] == "export":
        print(write_export(*sys.argv[2:3]))
    elif len(sys.argv) == 3 and sys.argv[1] == "search":
        books = json.loads(Path("build/search.json").read_text(encoding="utf-8"))["books"]
        for b in search(sys.argv[2], books):
            print(f'{b["isbn"]}\t{b["edition"]}\t{b["title"]}\t{"active" if b["active"] else "inactive"}')
    else:
        rows = load()
        print(json.dumps({"rows": len(rows), "unique_isbns": len({r["isbn"] for r in rows}),
                          "keys": [search_key(r["title"]) for r in rows]}, ensure_ascii=False))
EOF
